<script setup>
import { computed, ref, watch } from 'vue';
import { api } from '../../services/api';
import SvgIcon from '../SvgIcon.vue';
const props = defineProps({ projectId: String, state: Object, episodeId: String, episodes: Array });
const emit = defineEmits(['refresh', 'error', 'select-episode']);
const script = ref({ scenes: [] }); const busy = ref(false); const selected = ref(0); const compare = ref(false); const showHistory = ref(false); const revisions = ref([]);
const episodeState = computed(() => props.state?.episode_state || props.state);
const totalDuration = computed(() => script.value.scenes.reduce((sum, scene) => sum + Number(scene.duration_seconds || 0), 0));
const totalLabel = computed(() => `${Math.floor(totalDuration.value / 60)} 分 ${totalDuration.value % 60} 秒`);
const sourceChapters = computed(() => script.value.source_chapters || []);
watch(() => episodeState.value, s => {
  script.value = JSON.parse(JSON.stringify(s?.content?.scenes ? s.content : { scenes: [] }));
  script.value.scenes.forEach(scene => { scene.narrative ||= scene.action || ''; scene.plot_beats ||= []; scene.character_change ||= ''; scene.scene_outcome ||= ''; });
  selected.value = 0;
}, { immediate: true });
async function generate() { if (!props.episodeId) return emit('error', '请先选择剧集'); busy.value = true; try { await api.generateStage(props.projectId, 4, props.episodeId); emit('refresh'); } catch(e) { emit('error', e.message); } finally { busy.value = false; } }
async function save() { if (!props.episodeId || !script.value.scenes.length) return; script.value.total_duration = totalDuration.value; try { return await api.saveStage(props.projectId, 4, script.value, props.episodeId); } catch(e) { emit('error', e.message); throw e; } }
async function review() { busy.value = true; try { await save(); await api.reviewStage(props.projectId, 4, props.episodeId); emit('refresh'); } catch(e) { emit('error', e.message); } finally { busy.value = false; } }
async function loadHistory() { if (!episodeState.value?.id) return; revisions.value = await api.revisions(episodeState.value.id); showHistory.value = true; }
function addScene() { script.value.scenes.push({ scene_number: script.value.scenes.length + 1, duration_seconds: 30, location: '', time_environment: '', characters: [], narrative: '', plot_beats: [], character_change: '', scene_outcome: '', action: '', dialogue: [], internal_monologue: '', narration: '', transition: '', pacing: '' }); selected.value = script.value.scenes.length - 1; }
function dialogueText(scene) { return (scene.dialogue || []).map(d => `${d.character}：${d.line}${d.emotion ? `（${d.emotion}）` : ''}`).join('\n'); }
function setDialogue(scene, value) { scene.dialogue = value.split('\n').filter(Boolean).map(line => { const [character, ...rest] = line.split(/[：:]/); const raw = rest.join('：'); const emotion = raw.match(/（([^（）]+)）\s*$/)?.[1] || ''; return { character, line: raw.replace(/（[^（）]+）\s*$/, ''), emotion }; }); }
function beatText(scene) { return Array.isArray(scene.plot_beats) ? scene.plot_beats.join('\n') : scene.plot_beats || ''; }
function setBeats(scene, value) { scene.plot_beats = value.split('\n').map(v => v.trim()).filter(Boolean); }
defineExpose({ save });
</script>
<template>
  <div>
    <div class="script-toolbar"><div class="episode-select"><span>当前剧集</span><select :value="episodeId" @change="emit('select-episode', $event.target.value)"><option v-for="e in episodes" :key="e.id" :value="e.id">第 {{ e.episode_number }} 集 · {{ e.title }}</option></select></div><div v-if="script.scenes.length" class="total-duration"><span>本集总时长</span><strong>{{ totalLabel }}</strong><small>{{ script.scenes.length }} 个场景</small></div><div class="toolbar-actions"><button class="btn secondary small" @click="compare = !compare">原著对照 <span v-if="sourceChapters.length">{{ sourceChapters.length }}</span></button><button class="btn secondary small" @click="loadHistory">版本记录</button><button class="btn secondary small" :disabled="busy || !script.scenes.length" @click="review">AI 内容审阅</button><button class="btn primary small" :disabled="busy || !episodeId" @click="generate"><SvgIcon name="spark" :size="15" />{{ busy ? '正在完整改编原著…' : script.scenes.length ? '重新改编本集' : '从小说改编剧本' }}</button></div></div>
    <div class="script-purpose"><strong>小说改编工作台</strong><span>保留原著的事件、因果、人物动机、伏笔和台词，把小说转换成完整的场景剧本；这里不拆镜头，也不生成图片提示词。</span></div>
    <div class="script-workspace" :class="{ comparing: compare }">
      <aside v-if="compare" class="original-panel"><div class="panel-heading">本集原著对照</div><p v-if="!sourceChapters.length">重新改编后，这里会显示本集实际读取的原著章节，而不是只给一句提示。</p><details v-for="chapter in sourceChapters" :key="chapter.id" open><summary>{{ chapter.title }}<span>{{ (chapter.content || '').length }} 字</span></summary><pre>{{ chapter.content }}</pre></details><div v-if="script.quality_review" class="review-box"><strong>AI 内容审阅 · {{ script.quality_review.score }} 分</strong><p>{{ script.quality_review.summary }}</p><div v-for="(issue, i) in script.quality_review.issues" :key="i" class="issue"><b>{{ issue.severity }}</b>{{ issue.issue }}<small>{{ issue.suggestion }}</small></div></div></aside>
      <section class="editor-panel">
        <div v-if="!script.scenes.length" class="empty-content"><SvgIcon name="edit" :size="29" /><h3>本集还没有完整剧本</h3><p>AI 会按本集规划读取对应小说章节，长文自动分段改编，保留完整情节后再整理成场景。</p><button class="btn primary" :disabled="busy || !episodeId" @click="generate">从小说改编剧本</button></div>
        <template v-else>
          <div class="episode-script-head"><label>本集完整剧情梗概<textarea v-model="script.summary" placeholder="这一集从什么局面开始，经历了哪些变化，最终停在哪里"></textarea></label><label>改编与压缩说明<textarea v-model="script.adaptation_notes" placeholder="保留的重要情节，以及因时长压缩的内容；没有压缩也可以注明"></textarea></label></div>
          <div class="scene-tabs"><button v-for="(scene, i) in script.scenes" :key="i" :class="{ active: selected === i }" @click="selected = i">场景 {{ i + 1 }}</button><button class="add-scene" @click="addScene">+ 添加</button></div>
          <div v-if="script.scenes[selected]" class="scene-editor">
            <div class="scene-heading"><div><span>SCENE {{ String(selected + 1).padStart(2, '0') }}</span><h3>本场发生了什么</h3></div><small>先定故事，再做分镜</small></div>
            <div class="form-grid scene-basics"><label>场景地点<input v-model="script.scenes[selected].location" /></label><label>时间与环境<input v-model="script.scenes[selected].time_environment" /></label><label>场景时长（秒）<input type="number" min="1" v-model.number="script.scenes[selected].duration_seconds" /></label></div>
            <label>出场角色<input v-model="script.scenes[selected].characters" placeholder="许宁、姐姐" /></label>
            <label class="narrative-field">本场完整叙事<textarea v-model="script.scenes[selected].narrative" placeholder="按起因、经过和结果讲清楚本场戏：人物为何来到这里，做了什么，发现什么，如何反应，局面发生什么变化。"></textarea><small>这是剧本主体，应能独立读懂剧情，不只是给 AI 的画面描述。</small></label>
            <label>本场事件顺序<textarea :value="beatText(script.scenes[selected])" @input="setBeats(script.scenes[selected], $event.target.value)" placeholder="每行一个事件，保留关键动作、伏笔、信息揭示和人物反应"></textarea></label>
            <div class="form-grid"><label>人物状态与情绪变化<textarea v-model="script.scenes[selected].character_change" placeholder="开场怎样，经历事件后发生什么变化"></textarea></label><label>本场结果与后续衔接<textarea v-model="script.scenes[selected].scene_outcome" placeholder="本场结束时的局面，以及为什么进入下一场"></textarea></label></div>
            <label>原著台词与情绪<textarea :value="dialogueText(script.scenes[selected])" @input="setDialogue(script.scenes[selected], $event.target.value)" placeholder="角色：台词（情绪）&#10;每行一句，尽量逐字保留原著台词"></textarea></label>
            <div class="form-grid"><label>内心独白<textarea v-model="script.scenes[selected].internal_monologue"></textarea></label><label>旁白<textarea v-model="script.scenes[selected].narration"></textarea></label></div>
            <details class="execution-details"><summary>分镜继承信息 <span>供下一阶段使用，不替代上方叙事</span></summary><label>可见动作与环境细节<textarea v-model="script.scenes[selected].action" class="action-input" placeholder="环境、人物位置、表情、动作先后、关键道具和光线"></textarea></label><div class="form-grid"><label>转场<input v-model="script.scenes[selected].transition" /></label><label>节奏<input v-model="script.scenes[selected].pacing" /></label></div></details>
            <div class="editor-actions"><span>保存后保留完整版本记录；退回修改小说或规划后，可重新改编本集。</span><button class="btn primary small" @click="save">保存完整剧本</button></div>
          </div>
        </template>
      </section>
    </div>
    <div v-if="showHistory" class="modal-mask" @click.self="showHistory = false"><div class="modal clean-modal"><div class="history-heading"><h2>剧本版本记录</h2><button class="icon-btn" @click="showHistory = false">×</button></div><p v-if="!revisions.length" class="muted">还没有历史版本，首次修改保存后会自动记录。</p><details v-for="r in revisions" :key="r.id"><summary>版本 {{ r.revision_number }} · {{ r.note }} · {{ new Date(r.created_at).toLocaleString() }}</summary><pre>{{ JSON.stringify(r.content, null, 2) }}</pre></details></div></div>
  </div>
</template>
<style scoped>
.script-toolbar{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:14px;flex-wrap:wrap}.total-duration{display:flex;align-items:center;gap:8px;background:var(--accent-soft);color:var(--accent);border-radius:8px;padding:7px 11px}.total-duration span,.total-duration small{font-size:10px}.total-duration strong{font-size:14px}.script-purpose{display:flex;align-items:center;gap:12px;padding:12px 15px;margin-bottom:14px;border:1px solid var(--border);border-radius:9px;background:var(--surface)}.script-purpose strong{font-size:12px;white-space:nowrap}.script-purpose span{font-size:11px;line-height:1.6;color:var(--text-secondary)}.scene-basics{grid-template-columns:1fr 1fr 140px}.scene-editor label small{display:block;color:var(--text-tertiary);font-weight:400;margin-top:5px}.episode-select{display:flex;align-items:center;gap:9px;font-size:12px;color:var(--text-secondary)}.episode-select select{min-width:240px}.toolbar-actions{display:flex;gap:7px;flex-wrap:wrap}.script-workspace{display:grid;grid-template-columns:1fr;gap:14px}.script-workspace.comparing{grid-template-columns:minmax(280px,36%) 1fr}.original-panel,.editor-panel{background:var(--surface);border:1px solid var(--border);border-radius:11px;overflow:hidden}.original-panel{padding:18px;color:var(--text-secondary);font-size:13px;line-height:1.7;max-height:900px;overflow:auto}.panel-heading{font-weight:650;color:var(--text);border-bottom:1px solid var(--border);padding-bottom:12px}.original-panel details{border-top:1px solid var(--border);padding:12px 0}.original-panel summary{display:flex;justify-content:space-between;gap:10px;color:var(--text);cursor:pointer;font-weight:600}.original-panel summary span{font-size:10px;color:var(--text-tertiary)}.original-panel details pre{white-space:pre-wrap;word-break:break-word;font:12px/1.9 var(--font);color:var(--text-secondary);max-height:480px;overflow:auto;background:var(--page);padding:12px;border-radius:7px}.review-box{margin-top:20px}.review-box strong{color:var(--text)}.issue{padding:10px 0;border-top:1px solid var(--border)}.issue b{display:inline-block;color:#b45309;margin-right:6px;font-size:11px}.issue small{display:block;margin-top:4px}.episode-script-head{display:grid;grid-template-columns:1fr 1fr;gap:14px;padding:18px 20px;border-bottom:1px solid var(--border);background:#fafbfc}.episode-script-head label{font-size:12px;font-weight:600}.episode-script-head textarea{display:block;width:100%;min-height:86px;margin-top:6px;line-height:1.7}.scene-tabs{display:flex;gap:3px;padding:10px 12px;border-bottom:1px solid var(--border);overflow:auto}.scene-tabs button{background:transparent;color:var(--text-secondary);font-size:12px;padding:8px 12px;white-space:nowrap}.scene-tabs button.active{background:var(--accent-soft);color:var(--accent)}.scene-tabs .add-scene{margin-left:auto}.scene-editor{padding:20px}.scene-heading{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--border);padding-bottom:14px}.scene-heading span{font-size:10px;letter-spacing:1.3px;color:var(--accent);font-weight:700}.scene-heading h3{margin:4px 0 0;font-size:18px}.scene-heading>small{color:var(--text-tertiary);font-size:11px}.scene-editor label{display:block;font-size:12px;font-weight:600;margin:12px 0}.scene-editor input,.scene-editor textarea{width:100%;margin-top:6px}.scene-editor textarea{min-height:75px;line-height:1.75}.scene-editor .narrative-field textarea{min-height:190px;font-size:14px;line-height:1.9;background:#fcfcfd}.scene-editor .action-input{min-height:120px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.execution-details{margin-top:20px;border:1px solid var(--border);border-radius:9px;background:#fafbfc;padding:0 14px}.execution-details summary{cursor:pointer;padding:13px 0;font-size:12px;font-weight:650}.execution-details summary span{font-weight:400;color:var(--text-tertiary);margin-left:8px}.execution-details[open] summary{border-bottom:1px solid var(--border)}.execution-details .form-grid{padding-bottom:12px}.editor-actions{display:flex;align-items:center;justify-content:space-between;gap:16px;border-top:1px solid var(--border);padding-top:15px;margin-top:18px}.editor-actions span{font-size:11px;color:var(--text-secondary)}.empty-content{text-align:center;padding:110px 20px;color:var(--text-secondary)}.empty-content h3{color:var(--text)}.history-heading{display:flex;justify-content:space-between}.clean-modal details{border-top:1px solid var(--border);padding:12px 0}.clean-modal summary{cursor:pointer;font-size:13px}.clean-modal pre{max-height:300px;overflow:auto;background:var(--page);padding:12px;font-size:11px;white-space:pre-wrap}@media(max-width:900px){.script-toolbar{align-items:flex-start;flex-direction:column}.script-workspace.comparing{grid-template-columns:1fr}.original-panel{max-height:500px}.script-purpose{align-items:flex-start;flex-direction:column;gap:4px}}@media(max-width:600px){.form-grid,.episode-script-head{grid-template-columns:1fr}.episode-select{align-items:flex-start;flex-direction:column}.episode-select select{min-width:100%;width:100%}.scene-heading>small{display:none}}
</style>
